public with sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String CLOSED_WON = 'Closed Won';
    private static final String ERR_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String ERR_AMOUNT_CHANGED_ON_WON = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        List<Opportunity> opportunities = (List<Opportunity>) Records;

        for (Opportunity opp : opportunities)
        {
            if (opp.Amount != null && opp.Amount < 0)
            {
                error(ERR_NEGATIVE_AMOUNT, opp, Opportunity.Amount);
            }

            if (existingRecords != null && opp.Id != null && existingRecords.containsKey(opp.Id))
            {
                Opportunity existing = (Opportunity) existingRecords.get(opp.Id);

                if (existing.StageName == CLOSED_WON && opp.Amount != existing.Amount)
                {
                    error(ERR_AMOUNT_CHANGED_ON_WON, opp, Opportunity.Amount);
                }
            }
        }
    }
}
