public with sharing class AccountCountrySync {

    public static void syncMailingCountry(Map<Id, Account> newAccounts, Map<Id, Account> oldAccounts) {
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> previousBillingCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newBillingCountryByAccountId = new Map<Id, String>();

        for (Id accountId : newAccounts.keySet()) {
            Account newAccount = newAccounts.get(accountId);
            Account oldAccount = oldAccounts.get(accountId);

            if (oldAccount != null && newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccountIds.add(accountId);
                previousBillingCountryByAccountId.put(accountId, oldAccount.BillingCountry);
                newBillingCountryByAccountId.put(accountId, newAccount.BillingCountry);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // One query, scoped only to contacts belonging to accounts whose BillingCountry changed.
        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            String previousBillingCountry = previousBillingCountryByAccountId.get(contact.AccountId);
            String newBillingCountry = newBillingCountryByAccountId.get(contact.AccountId);

            Boolean mailingCountryIsBlank = String.isBlank(contact.MailingCountry);
            Boolean newBillingCountryIsBlank = String.isBlank(newBillingCountry);
            Boolean contactFollowsAccount = mailingCountryIsBlank
                || contact.MailingCountry == previousBillingCountry;

            if (contactFollowsAccount
                    && !(mailingCountryIsBlank && newBillingCountryIsBlank)
                    && contact.MailingCountry != newBillingCountry) {
                contact.MailingCountry = newBillingCountry;
                contactsToUpdate.add(contact);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
