    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                childIds.add(childId);
                parentIds.add(parentId);
            }
        }

        if (childIds.isEmpty() || parentIds.isEmpty()) {
            return;
        }

        List<npe4__Relationship__c> existingRelationships = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
            OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ];

        Map<Id, Set<Id>> existingByContact = new Map<Id, Set<Id>>();
        for (npe4__Relationship__c rel : existingRelationships) {
            if (!existingByContact.containsKey(rel.npe4__Contact__c)) {
                existingByContact.put(rel.npe4__Contact__c, new Set<Id>());
            }
            existingByContact.get(rel.npe4__Contact__c).add(rel.npe4__RelatedContact__c);
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            Boolean alreadyExists = false;
            if (existingByContact.containsKey(childId) && existingByContact.get(childId).contains(parentId)) {
                alreadyExists = true;
            }
            if (!alreadyExists && existingByContact.containsKey(parentId) && existingByContact.get(parentId).contains(childId)) {
                alreadyExists = true;
            }

            if (!alreadyExists) {
                toInsert.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));
            }
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
