/**
 * Trigger Action: creates an onboarding Task for the Account owner when a new
 * Account of Type 'Customer - Direct' or 'Customer - Channel' is inserted.
 *
 * Registered via the Trigger_Action__mdt record TA_Account_CreateOnboardingTask
 * (After_Insert__c = Account, Order__c = 10).
 *
 * Runs in the after insert context because Task.WhatId requires the new Account
 * Id, and because Account.OwnerId is only guaranteed to be populated after the
 * platform assigns the record's default owner.
 *
 * Bulk-safe: every qualifying Account contributes one Task and all Tasks are
 * inserted with a single DML statement. When no Account qualifies, the method
 * returns before any DML is performed.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer TASK_DUE_IN_DAYS = 7;

    public void afterInsert(List<SObject> triggerNew) {
        List<Account> accountsToOnboard = new List<Account>();

        for (SObject triggerRecord : triggerNew) {
            Account accountRecord = (Account) triggerRecord;
            if (ONBOARDING_ACCOUNT_TYPES.contains(accountRecord.Type)) {
                accountsToOnboard.add(accountRecord);
            }
        }

        // No qualifying Accounts -> no DML at all.
        if (accountsToOnboard.isEmpty()) {
            return;
        }

        Date activityDate = Date.today().addDays(TASK_DUE_IN_DAYS);
        List<Task> onboardingTasks = new List<Task>();

        for (Account accountRecord : accountsToOnboard) {
            onboardingTasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = accountRecord.Id,
                    OwnerId = accountRecord.OwnerId,
                    ActivityDate = activityDate,
                    Status = TASK_STATUS,
                    Priority = TASK_PRIORITY
                )
            );
        }

        // Single DML statement for the whole trigger execution.
        insert onboardingTasks;
    }
}
